window.DICE_IMAGES = {
    'black_die_success': 'data:image/png;base64,',
    'black_die_crit': 'data:image/png;base64,',
    'red_die_success': 'data:image/png;base64,',
    'red_die_messycrit': 'data:image/png;base64,',
    'red_die_bestial': 'data:image/png;base64,',
};
window.cinematicRollQueue = [];
window.isCinematicPlaying = false;

/**
 * Retrieves the user's preference for whether dice animations should be played.
 * It interacts with the browser's localStorage.
 * 
 * @returns {boolean} True if dice animations are enabled (or not set), false otherwise.
 */
window.getDiceAnimationSetting = function() {
    // Read the stored dice animation preference string from browser localStorage
    const savedAnimationSetting = localStorage.getItem('vtm_dice_animations');
    return savedAnimationSetting !== 'false';
};

/**
 * Saves the user's preference for dice animations to localStorage.
 * 
 * @param {boolean} isEnabled - Whether dice animations should be turned on.
 */
window.setDiceAnimationSetting = function(isEnabled) {
    // Persist the dice animation preference string into browser localStorage
    localStorage.setItem('vtm_dice_animations', isEnabled ? 'true' : 'false');
};

/**
 * Initializes the settings checkbox when the DOM is fully loaded.
 * It reads the current setting and sets up an event listener to update it when changed.
 */
// Register a DOMContentLoaded listener on the document to initialize the dice animation toggle
document.addEventListener('DOMContentLoaded', () => {
    // Query the DOM for the dice animations setting checkbox element by its ID
    const diceAnimationsCheckboxElement = document.getElementById('settingDiceAnimations');
    if (diceAnimationsCheckboxElement) {
        diceAnimationsCheckboxElement.checked = getDiceAnimationSetting();
        // Attach a change event listener to the checkbox to save updates when toggled
        diceAnimationsCheckboxElement.addEventListener('change', (changeEvent) => {
            setDiceAnimationSetting(changeEvent.target.checked);
        });
    }
});

/**
 * Opens a draggable editor overlay to customize the position and size of the dice rolling tray.
 * It creates a DOM element representing the tray area, binds mouse events for dragging, 
 * and reads the last known dimensions from localStorage.
 */
window.openTrayEditor = function() {
    // Query the DOM to check if the tray editor box is already open
    if (document.getElementById('trayEditorBox')) return;
    
    // Read the saved dice tray dimensions from browser localStorage
    let savedTrayDimensions = JSON.parse(localStorage.getItem('vtm_dice_tray') || 'null');
    if (!savedTrayDimensions) {
        savedTrayDimensions = { w: 600, h: 400, x: window.innerWidth / 2 - 300, y: window.innerHeight / 2 - 200 };
    }
    
    // Create a new div element in the DOM to serve as the interactive dice tray editor box
    const trayEditorElement = document.createElement('div');
    trayEditorElement.id = 'trayEditorBox';
    trayEditorElement.style.width = savedTrayDimensions.w + 'px';
    trayEditorElement.style.height = savedTrayDimensions.h + 'px';
    trayEditorElement.style.left = savedTrayDimensions.x + 'px';
    trayEditorElement.style.top = savedTrayDimensions.y + 'px';
    
    trayEditorElement.innerHTML = `
        <div id="trayEditorHandle">
            <span><i class="fa-solid fa-up-down-left-right"></i> Drag to Move</span>
            <button onclick="saveTrayEditor()" class="btn-action-solid" style="padding: 2px 8px; font-size: 11px;">Save & Close</button>
        </div>
        <div style="flex: 1; display:flex; align-items:center; justify-content:center; color: #ef4444; opacity: 0.5; font-size: 24px; pointer-events: none;">
            <i class="fa-solid fa-down-right-and-up-left-to-center" style="position:absolute; bottom:5px; right:5px; font-size: 16px;"></i>
        </div>
    `;
    // Append the tray editor element to the document body
    document.body.appendChild(trayEditorElement);
    
    // Query the DOM for the tray editor drag handle element by its ID
    const trayHandleElement = document.getElementById('trayEditorHandle');
    let isDragging = false;
    let startX, startY, startLeft, startTop;
    
    // Begin dragging when the user presses the mouse down on the handle
    trayHandleElement.addEventListener('mousedown', (mouseEvent) => {
        isDragging = true;
        startX = mouseEvent.clientX;
        startY = mouseEvent.clientY;
        startLeft = trayEditorElement.offsetLeft;
        startTop = trayEditorElement.offsetTop;
    });
    
    // Update position on mouse movement if dragging
    document.addEventListener('mousemove', (mouseEvent) => {
        if (!isDragging) return;
        const deltaX = mouseEvent.clientX - startX;
        const deltaY = mouseEvent.clientY - startY;
        trayEditorElement.style.left = (startLeft + deltaX) + 'px';
        trayEditorElement.style.top = (startTop + deltaY) + 'px';
    });
    
    // Stop dragging when the user releases the mouse button
    document.addEventListener('mouseup', () => {
        isDragging = false;
    });
};

/**
 * Saves the current position and size of the tray editor to localStorage
 * and removes the editor element from the DOM.
 */
window.saveTrayEditor = function() {
    // Query the DOM for the tray editor box element by its ID
    const trayEditorElement = document.getElementById('trayEditorBox');
    if (trayEditorElement) {
        const trayDimensionsState = {
            w: trayEditorElement.offsetWidth,
            h: trayEditorElement.offsetHeight,
            x: trayEditorElement.offsetLeft,
            y: trayEditorElement.offsetTop
        };
        // Save the serialized tray dimensions and coordinates to browser localStorage
        localStorage.setItem('vtm_dice_tray', JSON.stringify(trayDimensionsState));
        trayEditorElement.remove();
    }
};

const playedCinematicRollKeys = new Set();

function updateDiceQueueBadge() {
    const badgeEl = document.getElementById('diceQueueBadge');
    if (!badgeEl) return;
    const count = Array.isArray(window.cinematicRollQueue) ? window.cinematicRollQueue.length : 0;
    if (count > 0) {
        badgeEl.style.display = 'inline-flex';
        badgeEl.textContent = count === 1 ? 'UP NEXT: 1 ROLL QUEUED' : `UP NEXT: ${count} ROLLS QUEUED`;
    } else {
        badgeEl.style.display = 'none';
    }
}

/**
 * Enqueues a dice roll to be shown cinematically, or bypasses the animation 
 * to directly append it to the ledger if animations are turned off.
 * 
 * @param {Object} rollResult - The result object containing details of the roll.
 */
window.enqueueCinematicRoll = function(rollResult) {
    if (!rollResult) return;
    const dedupKey = rollResult.roll_uid || (rollResult.id ? `roll_${rollResult.id}_${rollResult.roller_name || ''}` : null);
    if (dedupKey) {
        if (playedCinematicRollKeys.has(dedupKey)) return;
        playedCinematicRollKeys.add(dedupKey);
        if (playedCinematicRollKeys.size > 300) {
            const oldest = playedCinematicRollKeys.values().next().value;
            playedCinematicRollKeys.delete(oldest);
        }
    }
    if (!getDiceAnimationSetting()) {
        appendDiceRollToLedger(rollResult);
        return;
    }
    window.cinematicRollQueue.push(rollResult);
    updateDiceQueueBadge();
    processCinematicQueue();
};

/**
 * Processes the next roll in the cinematic queue.
 * Ensures that only one cinematic roll plays at a time.
 */
function processCinematicQueue() {
    if (window.isCinematicPlaying || window.cinematicRollQueue.length === 0) {
        updateDiceQueueBadge();
        return;
    }
    window.isCinematicPlaying = true;
    const currentRollResult = window.cinematicRollQueue.shift();
    updateDiceQueueBadge();
    playCinematicRoll(currentRollResult);
}

/**
 * Generates the SVG HTML representation of a 10-sided die (D10).
 * It calculates the color and symbol based on whether it is a regular die or a hunger die, 
 * as well as the value rolled (success, critical, messy critical, bestial failure).
 * 
 * @param {number|string} dieValue - The numerical value rolled on the die.
 * @param {boolean} isHunger - Whether the die is a hunger die (red) or a regular die (black).
 * @param {number} rotationState - The 3D rotation state (0 for flat, 1 for edge-on, 2 for left bevel, 4 for right bevel).
 * @returns {string} The HTML string for the SVG rendering of the die.
 */
function renderD10Svg(dieValue, isHunger, rotationState = 0) {
    const parsedDieValue = parseInt(dieValue, 10);
    const numericDieValue = isNaN(parsedDieValue) ? 1 : parsedDieValue;
    const isTen = numericDieValue === 10;
    const isSuccess = numericDieValue >= 6;
    const isBestial = isHunger && numericDieValue === 1;
    const isMessy = isHunger && isTen;
    const gradientElementId = 'd10_' + Math.random().toString(36).substr(2, 6);
    
    let symbolContent = '';
    
    if (isBestial) {
        symbolContent = `<image href="${DICE_IMAGES['red_die_bestial']}" x="29" y="28" width="42" height="42" preserveAspectRatio="xMidYMid meet" />`;
    } else if (isMessy) {
        symbolContent = `<image href="${DICE_IMAGES['red_die_messycrit']}" x="28" y="22" width="44" height="52" preserveAspectRatio="xMidYMid meet" />`;
    } else if (isTen && !isHunger) {
        symbolContent = `<image href="${DICE_IMAGES['black_die_crit']}" x="28" y="22" width="44" height="52" preserveAspectRatio="xMidYMid meet" />`;
    } else if (isSuccess && isHunger) {
        symbolContent = `<image href="${DICE_IMAGES['red_die_success']}" x="28" y="22" width="44" height="52" preserveAspectRatio="xMidYMid meet" />`;
    } else if (isSuccess && !isHunger) {
        symbolContent = `<image href="${DICE_IMAGES['black_die_success']}" x="28" y="22" width="44" height="52" preserveAspectRatio="xMidYMid meet" />`;
    }

    const colorTopLeft = isHunger ? '#e02828' : '#3a424e';
    const colorTopRight = isHunger ? '#9c1414' : '#262d36';
    const colorBottomLeft = isHunger ? '#3b0404' : '#111418';
    const colorBottomRight = isHunger ? '#280202' : '#0a0c0e';
    const colorCenterGradientStart = isHunger ? '#c21a1a' : (isTen ? '#2c333d' : '#22272e');
    const colorCenterGradientEnd = isHunger ? '#6e0a0a' : (isTen ? '#181c22' : '#101317');
    const strokeRidgeLine = isHunger ? 'rgba(255,120,120,0.45)' : isTen ? 'rgba(251,191,36,0.55)' : 'rgba(255,255,255,0.25)';
    
    let glowClass = '';
    if (isHunger) {
        glowClass = isMessy ? 'glow-messy-crit' : isBestial ? 'glow-bestial-fail' : 'glow-hunger';
    } else {
        glowClass = isTen ? 'glow-crit' : isSuccess ? 'glow-success' : '';
    }

    let svgInner = '';
    
    if (rotationState === 1) {
        // EDGE-ON VIEW (No face up)
        svgInner = `
            <polygon points="50,4 8,40 8,52 50,40" fill="${colorTopLeft}"/>
            <polygon points="50,40 8,52 8,64 50,96" fill="${colorBottomLeft}"/>
            <polygon points="50,4 50,40 92,52 92,40" fill="${colorTopRight}"/>
            <polygon points="50,40 50,96 92,64 92,52" fill="${colorBottomRight}"/>
            <line x1="50" y1="4" x2="50" y2="96" stroke="${strokeRidgeLine}" stroke-width="1.2"/>
            <line x1="8" y1="52" x2="50" y2="40" stroke="${strokeRidgeLine}" stroke-width="1.0"/>
            <line x1="50" y1="40" x2="92" y2="52" stroke="${strokeRidgeLine}" stroke-width="1.0"/>
            <polyline points="50,4 8,40 8,64 50,96 92,64 92,40 50,4" fill="none" stroke="rgba(0,0,0,0.7)" stroke-width="0.9"/>
        `;
    } else {
        // FLAT VIEW OR SIDE BEVEL VIEW
        let transformGroup = '';
        if (rotationState === 2) {
            // Symbol on Left Bevel
            transformGroup = `<g transform="matrix(0.3, -0.15, 0, 0.4, 12, 30)">${symbolContent}</g>`;
        } else if (rotationState === 4) {
            // Symbol on Right Bevel
            transformGroup = `<g transform="matrix(0.3, 0.15, 0, 0.4, 62, 22)">${symbolContent}</g>`;
        } else {
            // Normal Flat Symbol
            transformGroup = symbolContent;
        }

        svgInner = `
            <defs>
                <linearGradient id="${gradientElementId}_center" x1="0%" y1="0%" x2="0%" y2="100%">
                    <stop offset="0%" stop-color="${colorCenterGradientStart}"/>
                    <stop offset="100%" stop-color="${colorCenterGradientEnd}"/>
                </linearGradient>
            </defs>
            <polygon points="50,6 92,42 92,66 50,98 8,66 8,42" fill="rgba(0,0,0,0.6)"/>
            <polygon points="50,4 8,40 8,64 24,60" fill="${colorTopLeft}"/>
            <polygon points="50,4 92,40 92,64 76,60" fill="${colorTopRight}"/>
            <polygon points="24,60 8,64 50,96 50,78" fill="${colorBottomLeft}"/>
            <polygon points="76,60 92,64 50,96 50,78" fill="${colorBottomRight}"/>
            <polygon points="50,4 76,60 50,78 24,60" fill="url(#${gradientElementId}_center)"/>
            <line x1="50" y1="4" x2="24" y2="60" stroke="${strokeRidgeLine}" stroke-width="0.9"/>
            <line x1="50" y1="4" x2="76" y2="60" stroke="${strokeRidgeLine}" stroke-width="0.8"/>
            <line x1="24" y1="60" x2="50" y2="78" stroke="rgba(0,0,0,0.65)" stroke-width="0.9"/>
            <line x1="76" y1="60" x2="50" y2="78" stroke="rgba(0,0,0,0.75)" stroke-width="0.9"/>
            <line x1="50" y1="78" x2="50" y2="96" stroke="rgba(0,0,0,0.85)" stroke-width="1.1"/>
            <polyline points="50,4 8,40 8,64 50,96 92,64 92,40 50,4" fill="none" stroke="rgba(0,0,0,0.7)" stroke-width="0.9"/>
            ${transformGroup}
        `;
    }

    return `<div class="v5-d10-die-wrapper ${glowClass}" title="${isHunger ? 'Hunger Die' : 'Regular Die'}: ${numericDieValue}">
        <svg viewBox="0 0 100 100" class="v5-d10-svg">
            ${svgInner}
        </svg>
    </div>`;
}
window.renderD10Svg = renderD10Svg;

/**
 * Initiates the physical 3D-like dice rolling animation.
 * Creates an overlay and physics tray, spawns dice elements, applies custom 
 * pseudophysics for bouncing, rolling, and colliding, and eventually registers 
 * the settled results in the ledger.
 * 
 * @param {Object} rollResult - The outcome of the dice roll containing values for regular and hunger dice.
 */
function playCinematicRoll(rollResult) {
    // Remove any stale overlay so rolls always play cleanly one after another
    document.querySelectorAll('.dice-cinematic-overlay').forEach(el => el.remove());

    // Retrieve the saved dice tray dimensions and coordinates from browser localStorage
    let savedTrayDimensions = JSON.parse(localStorage.getItem('vtm_dice_tray') || 'null');
    if (!savedTrayDimensions) {
        savedTrayDimensions = { w: 600, h: 400, x: window.innerWidth / 2 - 300, y: window.innerHeight / 2 - 200 };
    }
    const vw = window.innerWidth || 1280;
    const vh = window.innerHeight || 768;
    const clampedW = Math.min(Math.max(300, savedTrayDimensions.w || 600), vw - 32);
    const clampedH = Math.min(Math.max(220, savedTrayDimensions.h || 400), vh - 80);
    const clampedX = Math.min(Math.max(16, savedTrayDimensions.x ?? (vw / 2 - clampedW / 2)), Math.max(16, vw - clampedW - 16));
    const clampedY = Math.min(Math.max(58, savedTrayDimensions.y ?? (vh / 2 - clampedH / 2)), Math.max(58, vh - clampedH - 16));
    savedTrayDimensions = { w: clampedW, h: clampedH, x: clampedX, y: clampedY };

    const rollerLabel = (rollResult.character_name && rollResult.character_name !== 'Action'
        ? `${rollResult.roller_name || 'Kindred'} — ${rollResult.character_name}`
        : (rollResult.roller_name || 'Kindred')).toUpperCase();
    const queuedCount = Array.isArray(window.cinematicRollQueue) ? window.cinematicRollQueue.length : 0;
    const queueBadgeStyle = queuedCount > 0 ? 'display:inline-flex;' : 'display:none;';
    const queueBadgeText = queuedCount === 1 ? 'UP NEXT: 1 ROLL QUEUED' : `UP NEXT: ${queuedCount} ROLLS QUEUED`;

    // Create a new div element in the DOM for the cinematic dice overlay
    const cinematicOverlayElement = document.createElement('div');
    cinematicOverlayElement.className = 'dice-cinematic-overlay';
    cinematicOverlayElement.innerHTML = `
        <div class="dice-soft-box" style="width: ${savedTrayDimensions.w}px; height: ${savedTrayDimensions.h}px; left: ${savedTrayDimensions.x}px; top: ${savedTrayDimensions.y}px;">
            <div style="position:absolute; top:10px; left:14px; right:14px; display:flex; align-items:center; justify-content:space-between; z-index:12; pointer-events:none;">
                <span style="font-family:'Cinzel',serif; font-size:13px; font-weight:700; color:#f8fafc; background:rgba(15,8,12,0.82); border:1px solid rgba(239,68,68,0.45); border-radius:6px; padding:4px 10px; letter-spacing:0.8px; text-shadow:0 1px 3px #000;"><i class="fa-solid fa-dice-d20" style="color:#ef4444;margin-right:6px;"></i>${rollerLabel}</span>
                <span id="diceQueueBadge" style="${queueBadgeStyle} align-items:center; gap:5px; font-size:11px; font-weight:800; color:#fde047; background:rgba(30,15,20,0.9); border:1px solid rgba(250,204,21,0.55); border-radius:20px; padding:4px 10px; letter-spacing:0.6px; box-shadow:0 0 12px rgba(250,204,21,0.25);">${queueBadgeText}</span>
            </div>
            <div class="dice-watermark">${(rollResult.roller_name || 'Kindred').toUpperCase()}</div>
            <div class="dice-soft-box-tray" id="dicePhysicsTray"></div>
        </div>
    `;
    // Append the cinematic dice overlay to the document body
    document.body.appendChild(cinematicOverlayElement);
    
    void cinematicOverlayElement.offsetWidth;
    cinematicOverlayElement.classList.add('active');
    
    // Query the DOM for the physics tray container element by its ID
    const physicsTrayElement = cinematicOverlayElement.querySelector('#dicePhysicsTray') || document.getElementById('dicePhysicsTray');
    // Measure the screen bounding rectangle of the physics tray
    const trayBoundingRect = physicsTrayElement.getBoundingClientRect();
    const trayWidth = Math.max(240, trayBoundingRect.width || savedTrayDimensions.w || 600);
    const trayHeight = Math.max(180, trayBoundingRect.height || savedTrayDimensions.h || 400);
    const baseTrayWidth = 600;
    // More aggressive scaling so the user can easily see the difference
    const widthRatio = Math.min(1.0, trayWidth / baseTrayWidth);
    const targetScale = Math.max(0.35, 0.25 + 0.75 * widthRatio);
    console.log(`[Dice Engine] Tray Width: ${trayWidth}, Target Scale: ${targetScale}`);

    let diceBodies = [];
    const regularResults = rollResult.regular_results ? rollResult.regular_results.toString().split(',').filter(Boolean) : [];
    const hungerResults = rollResult.hunger_results ? rollResult.hunger_results.toString().split(',').filter(Boolean) : [];
    
    // Choose a random starting "hand" position near the edge of the tray
    const handAngle = Math.random() * Math.PI * 2;
    const handRadius = Math.min(trayWidth, trayHeight) * 0.35;
    const handX = (trayWidth / 2) + Math.cos(handAngle) * handRadius;
    const handY = (trayHeight / 2) + Math.sin(handAngle) * handRadius;
    
    // Calculate toss vector toward the center
    const tossLength = Math.max(1, Math.sqrt(Math.pow((trayWidth / 2) - handX, 2) + Math.pow((trayHeight / 2) - handY, 2)));
    const tossDirectionX = ((trayWidth / 2) - handX) / tossLength;
    const tossDirectionY = ((trayHeight / 2) - handY) / tossLength;
    const tossForce = 42;
    const baseVelocityX = tossDirectionX * tossForce;
    const baseVelocityY = tossDirectionY * tossForce;
    
    /**
     * Helper function to instantiate and initialize a single die element on the board.
     * Sets its starting position, velocity, and rotation, adding it to the diceBodies array.
     * 
     * @param {string|number} finalDieValue - The final numerical value this die should settle on.
     * @param {boolean} isHunger - Whether the die is a hunger die.
     */
    function spawnDie(finalDieValue, isHunger) {
        // Create a new div element in the DOM to represent the animated die
        const dieElement = document.createElement('div');
        dieElement.className = 'cinematic-die';
        
        // Cluster tightly around the "hand"
        const initialPositionX = handX + ((Math.random() - 0.5) * 40);
        const initialPositionY = handY + ((Math.random() - 0.5) * 40);
        
        // Fanning out sideways
        const spread = 35;
        const spreadVelocityX = -tossDirectionY * ((Math.random() - 0.5) * spread); // Orthogonal X
        const spreadVelocityY = tossDirectionX * ((Math.random() - 0.5) * spread);  // Orthogonal Y
        
        // Add random forward/backward variation
        const speedVariation = 0.75 + Math.random() * 0.5; // 0.75x to 1.25x speed
        
        const velocityX = (baseVelocityX * speedVariation) + spreadVelocityX;
        const velocityY = (baseVelocityY * speedVariation) + spreadVelocityY;
        const angularVelocity = (Math.random() - 0.5) * 35;
        
        // Toss slightly upwards with gravity
        const scale = 3.2 * targetScale;
        const verticalVelocity = 0.035 + (Math.random() * 0.025);
        
        dieElement.style.position = 'absolute';
        dieElement.style.width = '80px';
        dieElement.style.height = '80px';
        dieElement.style.transformOrigin = 'center center';
        
        const initialTumbleValue = Math.floor(Math.random() * 10) + 1;
        dieElement.innerHTML = renderD10Svg(initialTumbleValue, isHunger, 0);
        physicsTrayElement.appendChild(dieElement);
        
        diceBodies.push({
            element: dieElement,
            finalValue: parseInt(finalDieValue, 10),
            isHunger,
            positionX: initialPositionX,
            positionY: initialPositionY,
            velocityX,
            velocityY,
            scale,
            verticalVelocity,
            angle: Math.random() * 360,
            angularVelocity,
            settled: false,
            faceFlipTimer: 0,
            sequenceIndex: Math.floor(Math.random() * 6),
            tumbleValue: initialTumbleValue,
            holdTimer: 220 + Math.random() * 120
        });
    }
    
    regularResults.forEach(dieValue => spawnDie(dieValue, false));
    hungerResults.forEach(dieValue => spawnDie(dieValue, true));
    
    // Read high-resolution current timestamp from the browser Performance API
    const rollStartTime = performance.now();
    const MAX_ROLL_MS = 2600; // Hard cap so dice never get stuck spinning indefinitely
    let lastTime = rollStartTime;
    let animationFrameId;
    let finished = false;

    function finalizeRoll() {
        if (finished) return;
        finished = true;
        // Cancel any pending browser animation frame callback
        if (animationFrameId) cancelAnimationFrame(animationFrameId);

        // Ensure every die displays its final settled SVG face cleanly
        diceBodies.forEach(dieBody => {
            if (!dieBody.settled) {
                dieBody.settled = true;
                dieBody.scale = targetScale;
                dieBody.velocityX = 0;
                dieBody.velocityY = 0;
                dieBody.angularVelocity = 0;
                dieBody.element.innerHTML = renderD10Svg(dieBody.finalValue, dieBody.isHunger, 0);
                dieBody.element.style.transform = `translate(${dieBody.positionX - 40}px, ${dieBody.positionY - 40}px) scale(${dieBody.scale}) rotate(${dieBody.angle}deg)`;
            }
        });

        // Schedule a timer to fade out the dice overlay after players have viewed the result
        setTimeout(() => {
            cinematicOverlayElement.classList.remove('active');
            // Schedule a timer to remove the overlay from the DOM after the CSS fade transition completes
            setTimeout(() => {
                cinematicOverlayElement.remove();
                appendDiceRollToLedger(rollResult);
                window.isCinematicPlaying = false;
                processCinematicQueue();
            }, 450);
        }, 2200);
    }
    
    /**
     * Physics loop called on each animation frame.
     * Handles movement, bouncing, friction, and collision detection between dice.
     * Flips the visible SVG state of the dice as they tumble, and finalizes them when settled.
     * 
     * @param {number} currentTimestamp - The current timestamp provided by requestAnimationFrame.
     */
    function updatePhysics(currentTimestamp) {
        if (finished) return;

        // Clamp dt so frame drops / VPN packet bursts never launch dice across the tray
        const rawDeltaTime = (currentTimestamp - lastTime) / 16.66;
        const deltaTime = Math.min(2.0, Math.max(0.1, rawDeltaTime));
        lastTime = currentTimestamp;
        const elapsedMs = currentTimestamp - rollStartTime;
        const forceSettle = elapsedMs >= MAX_ROLL_MS;
        
        const collisionRadius = 40 * targetScale;
        const minX = collisionRadius;
        const maxX = Math.max(collisionRadius, trayWidth - collisionRadius);
        const minY = collisionRadius;
        const maxY = Math.max(collisionRadius, trayHeight - collisionRadius);
        
        diceBodies.forEach(dieBody => {
            if (dieBody.settled) return;
            
            if (dieBody.holdTimer > 0 && !forceSettle) {
                dieBody.holdTimer -= (deltaTime * 16.66);
                dieBody.positionX += (Math.random() - 0.5) * 1.0;
                dieBody.positionY += (Math.random() - 0.5) * 1.0;
                dieBody.angle += dieBody.angularVelocity * deltaTime * 0.04;
                return;
            }
            
            if ((dieBody.scale > targetScale || dieBody.verticalVelocity > 0) && !forceSettle) {
                // Airborne physics
                dieBody.scale += dieBody.verticalVelocity * deltaTime;
                dieBody.verticalVelocity -= 0.0055 * deltaTime; // Gravity
                
                // Frame-rate independent air resistance
                const airDrag = Math.pow(0.99, deltaTime);
                const airSpinDrag = Math.pow(0.97, deltaTime);
                dieBody.velocityX *= airDrag;
                dieBody.velocityY *= airDrag;
                dieBody.angularVelocity *= airSpinDrag;
                
                if (dieBody.scale <= targetScale) {
                    if (dieBody.verticalVelocity < -0.022) {
                        // Impact table: Bounce!
                        dieBody.scale = targetScale;
                        dieBody.verticalVelocity = dieBody.verticalVelocity * -0.4; 
                        
                        // Lose horizontal speed to table impact
                        dieBody.velocityX *= 0.55;
                        dieBody.velocityY *= 0.55;
                        dieBody.angularVelocity = (dieBody.angularVelocity * 0.5) + (Math.random() - 0.5) * 24;
                    } else {
                        dieBody.scale = targetScale;
                        dieBody.verticalVelocity = 0;
                    }
                }
            } else {
                // Ground rolling physics with frame-rate independent friction
                dieBody.scale = targetScale;
                dieBody.verticalVelocity = 0;
                const groundFriction = Math.pow(0.90, deltaTime);
                const spinFriction = Math.pow(0.84, deltaTime);
                dieBody.velocityX *= groundFriction;
                dieBody.velocityY *= groundFriction;
                dieBody.angularVelocity *= spinFriction;
            }
            
            dieBody.positionX += dieBody.velocityX * deltaTime;
            dieBody.positionY += dieBody.velocityY * deltaTime;
            dieBody.angle += dieBody.angularVelocity * deltaTime;
            
            const restitution = -0.75;
            if (dieBody.positionX < minX) { dieBody.positionX = minX; dieBody.velocityX *= restitution; dieBody.angularVelocity *= 0.7; }
            if (dieBody.positionX > maxX) { dieBody.positionX = maxX; dieBody.velocityX *= restitution; dieBody.angularVelocity *= 0.7; }
            if (dieBody.positionY < minY) { dieBody.positionY = minY; dieBody.velocityY *= restitution; dieBody.angularVelocity *= 0.7; }
            if (dieBody.positionY > maxY) { dieBody.positionY = maxY; dieBody.velocityY *= restitution; dieBody.angularVelocity *= 0.7; }
            
            dieBody.faceFlipTimer += deltaTime;
            const isAirborne = (dieBody.scale > targetScale || dieBody.verticalVelocity > 0);
            const flipThreshold = isAirborne ? 8.0 : 2.8;
            const speed = Math.hypot(dieBody.velocityX, dieBody.velocityY);
            if (dieBody.faceFlipTimer > flipThreshold && (speed > 0.6 || Math.abs(dieBody.angularVelocity) > 2.5)) {
                dieBody.faceFlipTimer = 0;
                
                // Advance the rolling sequence index
                dieBody.sequenceIndex = (dieBody.sequenceIndex + 1) % 6;
                const rollSequence = [0, 1, 2, 1, 4, 1];
                const rotationState = rollSequence[dieBody.sequenceIndex];
                
                // Only generate a new random value if it's a "face-up" frame (state 0, 2, 4)
                if (rotationState !== 1) {
                    dieBody.tumbleValue = Math.floor(Math.random() * 10) + 1;
                }
                
                dieBody.element.innerHTML = renderD10Svg(dieBody.tumbleValue, dieBody.isHunger, rotationState);
            }
        });
        
        // Pairwise collision resolution (skip if forceSettle reached)
        if (!forceSettle) {
            for (let firstDieIndex = 0; firstDieIndex < diceBodies.length; firstDieIndex++) {
                for (let secondDieIndex = firstDieIndex + 1; secondDieIndex < diceBodies.length; secondDieIndex++) {
                    const firstDieBody = diceBodies[firstDieIndex];
                    const secondDieBody = diceBodies[secondDieIndex];
                    
                    if (firstDieBody.holdTimer > 0 || secondDieBody.holdTimer > 0) continue;
                    if (firstDieBody.settled && secondDieBody.settled) continue;
                    if (Math.abs(firstDieBody.scale - secondDieBody.scale) > 1.0) continue; 
                    
                    const deltaX = secondDieBody.positionX - firstDieBody.positionX;
                    const deltaY = secondDieBody.positionY - firstDieBody.positionY;
                    const distanceBetweenDice = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
                    const minimumCollisionDistance = collisionRadius * 2;
                    
                    if (distanceBetweenDice < minimumCollisionDistance && distanceBetweenDice > 0.001) {
                        const normalVectorX = deltaX / distanceBetweenDice;
                        const normalVectorY = deltaY / distanceBetweenDice;
                        const overlap = minimumCollisionDistance - distanceBetweenDice;
                        const pushX = (normalVectorX * overlap) * 0.5;
                        const pushY = (normalVectorY * overlap) * 0.5;
                        
                        // Clamp within tray bounds so separating dice doesn't ping-pong off walls
                        firstDieBody.positionX = Math.min(maxX, Math.max(minX, firstDieBody.positionX - pushX));
                        firstDieBody.positionY = Math.min(maxY, Math.max(minY, firstDieBody.positionY - pushY));
                        secondDieBody.positionX = Math.min(maxX, Math.max(minX, secondDieBody.positionX + pushX));
                        secondDieBody.positionY = Math.min(maxY, Math.max(minY, secondDieBody.positionY + pushY));
                        
                        const relativeVelocityX = firstDieBody.velocityX - secondDieBody.velocityX;
                        const relativeVelocityY = firstDieBody.velocityY - secondDieBody.velocityY;
                        const velocityAlongNormal = relativeVelocityX * normalVectorX + relativeVelocityY * normalVectorY;
                        
                        // Only transfer impulse/spin on meaningful impacts (prevents infinite micro-spin)
                        if (velocityAlongNormal > 1.2) {
                            const bounciness = 0.7;
                            const impulse = (1 + bounciness) * velocityAlongNormal / 2;
                            const impulseX = impulse * normalVectorX;
                            const impulseY = impulse * normalVectorY;
                            
                            firstDieBody.velocityX -= impulseX;
                            firstDieBody.velocityY -= impulseY;
                            secondDieBody.velocityX += impulseX;
                            secondDieBody.velocityY += impulseY;
                            
                            const spinKick = Math.min(14, velocityAlongNormal * 1.1);
                            firstDieBody.angularVelocity += (Math.random() - 0.5) * spinKick;
                            secondDieBody.angularVelocity += (Math.random() - 0.5) * spinKick;
                            if (velocityAlongNormal > 2.5) {
                                firstDieBody.settled = false;
                                secondDieBody.settled = false;
                            }
                        } else if (velocityAlongNormal > 0) {
                            // Dampen gentle contact so crowded dice come to rest quickly
                            firstDieBody.velocityX *= 0.6;
                            firstDieBody.velocityY *= 0.6;
                            secondDieBody.velocityX *= 0.6;
                            secondDieBody.velocityY *= 0.6;
                            firstDieBody.angularVelocity *= 0.5;
                            secondDieBody.angularVelocity *= 0.5;
                        }
                    }
                }
            }
        }
        
        let allSettled = true;
        diceBodies.forEach(dieBody => {
            const speed = Math.hypot(dieBody.velocityX, dieBody.velocityY);
            if (forceSettle || (dieBody.holdTimer <= 0 && dieBody.scale <= targetScale + 0.01 && speed < 0.65 && Math.abs(dieBody.angularVelocity) < 1.5)) {
                if (!dieBody.settled) {
                    dieBody.settled = true;
                    dieBody.scale = targetScale;
                    dieBody.verticalVelocity = 0;
                    dieBody.velocityX = 0;
                    dieBody.velocityY = 0;
                    dieBody.angularVelocity = 0;
                    dieBody.element.innerHTML = renderD10Svg(dieBody.finalValue, dieBody.isHunger, 0);
                }
            }
            if (!dieBody.settled) {
                allSettled = false;
            }
            dieBody.element.style.transform = `translate(${dieBody.positionX - 40}px, ${dieBody.positionY - 40}px) scale(${dieBody.scale}) rotate(${dieBody.angle}deg)`;
        });
        
        if (allSettled || diceBodies.length === 0) {
            finalizeRoll();
        } else {
            // Schedule the next physics update step on the browser's next animation frame
            animationFrameId = requestAnimationFrame(updatePhysics);
        }
    }
    
    // Start the physics animation loop on the browser's next animation frame
    animationFrameId = requestAnimationFrame(updatePhysics);
}

window.enqueueCinematicRoll = enqueueCinematicRoll;

